using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Windows;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using System.Windows.Threading;
namespace FlowShift {
public static class WheelTests {
 public static void Save(Window window,string path){window.UpdateLayout();window.Dispatcher.Invoke(new Action(()=>{}),DispatcherPriority.ApplicationIdle);var bitmap=new RenderTargetBitmap((int)Math.Ceiling(window.ActualWidth),(int)Math.Ceiling(window.ActualHeight),96,96,PixelFormats.Pbgra32);bitmap.Render(window);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using(var stream=File.Create(path))encoder.Save(stream);}
 public static int Render(string[] args){var app=new Application(){ShutdownMode=ShutdownMode.OnExplicitShutdown};var main=new MainWindow(true);Backend.Initialize(main.Pref).Wait();if(!Backend.Ready)return 2;var files=args.Skip(2).Where(File.Exists).ToArray();if(files.Length==0)return 3;var source=Backend.Detect(files[0]);var wheel=new RadialCompass(files,main.Engine.Common(files),WheelPresets.Category(files),2,null,true,main.Pref);int page=Array.IndexOf(args,"--page");if(page>=0)wheel.ChangePage(Int32.Parse(args[page+1])-1);int hover=Array.IndexOf(args,"--hover");if(hover>=0)wheel.Surface.Hover=Array.IndexOf(wheel.Targets,args[hover+1]);wheel.Show();Save(wheel,args[1]);app.Shutdown();return 0;}
 public static int Run(string dir){Directory.CreateDirectory(dir);var log=new List<string>();Action<bool,string> check=(ok,name)=>{if(!ok)throw new Exception("FAIL "+name);log.Add("PASS "+name);};Application app=null;try{
  string[] photoTargets={"png","webp","pdf","jpg","ico","bmp","tiff","avif","zip"};var routes=photoTargets.Select(f=>new Route(f,"test","")).ToList();var targets=WheelModel.Targets(routes,"Image");check(targets.SequenceEqual(new[]{"png","webp","pdf","jpg","ico","bmp","tiff",WheelModel.More}),"image ring priorities and more entry");
  check(WheelModel.Targets(new List<Route>(),"unknown").SequenceEqual(new[]{WheelModel.More}),"empty routes still offer floating window");check(WheelModel.Targets(new[]{new Route("docx","",""),new Route("txt","","")},"Pdf").SequenceEqual(new[]{"docx","txt",WheelModel.More}),"PDF ring only uses available formats");
  foreach(int count in new[]{1,2,3,4,5,6,7,8})for(int index=0;index<count;index++)check(WheelModel.Hit(WheelModel.Polar(152,-90+360.0*index/count),count)==index,"sector hit "+count+"/"+index);
  check(WheelModel.Hit(new Point(230,230),8)==-1,"release in center cancels");check(WheelModel.Hit(WheelModel.Polar(225,-90),8)==-1,"release outside cancels");check(WheelModel.Hit(WheelModel.Polar(152,-67.5),8)==-1,"sector gap does not select neighbor");
  check(WheelModel.Summary(new[]{"one.jpg"})=="1 JPG"&&WheelModel.Summary(new[]{"one.jpg","two.jpg"})=="2 JPG"&&WheelModel.Summary(new[]{"one.jpg","two.png"})=="2 个文件","single and multiple selection summaries");
  foreach(var work in new[]{new Rect(0,0,1920,1040),new Rect(-1920,-300,1920,1080),new Rect(0,0,420,320)})foreach(var point in new[]{work.TopLeft,work.BottomRight,new Point(work.Left+work.Width/2,work.Top+work.Height/2)})check(work.Contains(WheelModel.Placement(work,point,460)),"wheel stays inside monitor "+work+" "+point);
  app=new Application(){ShutdownMode=ShutdownMode.OnExplicitShutdown};string selected="";int callbacks=0;var wheel=new RadialCompass(new[]{"one.jpg","two.jpg"},routes,"Image",2,target=>{selected=target;callbacks++;},true);wheel.Show();wheel.ConfirmAt(WheelModel.Polar(152,-45));wheel.ConfirmAt(WheelModel.Polar(152,0));check(selected=="webp"&&callbacks==1,"right-release target commits exactly once");
  wheel=new RadialCompass(new[]{"one.jpg"},routes,"Image",2,target=>callbacks++,true);wheel.Show();wheel.ConfirmAt(new Point(230,230));check(callbacks==1,"center release never converts");
  wheel=new RadialCompass(new[]{"one.jpg"},routes,"Image",0,target=>callbacks++,true);wheel.Show();wheel.Cancel();check(callbacks==1,"keyboard-mode cancel never converts");
  selected="";wheel=new RadialCompass(new[]{"one.jpg"},routes,"Image",0,target=>selected=target,true);wheel.Show();wheel.ConfirmAt(WheelModel.Polar(152,-90+7*45));check(selected==WheelModel.More,"more sector uses separate action");
  Preferences.Home=Path.Combine(dir,"profile");var main=new MainWindow(true);main.Dock=new FloatingDock(main,true);string jpg=Path.Combine(dir,"one.jpg"),png=Path.Combine(dir,"two.png"),txt=Path.Combine(dir,"three.txt");File.WriteAllText(jpg,"");File.WriteAllText(png,"");File.WriteAllText(txt,"hello");var common=main.Engine.Common(new[]{jpg,png});check(common.Count>0&&WheelModel.Targets(common,"Image").Where(f=>f!=WheelModel.More).All(f=>main.Engine.Routes(jpg).Any(r=>r.Format==f)&&main.Engine.Routes(png).Any(r=>r.Format==f)),"multiple files use intersection of available routes");var mixed=main.Engine.Common(new[]{jpg,txt});check(!WheelModel.Targets(mixed,"").Contains("png"),"mixed incompatible files do not advertise PNG");main.RunWheelChoice(new[]{jpg,png},WheelModel.More);check(main.Dock.ShowingAllFormats&&!main.Dock.IsEdgeHidden&&!main.Dock.IsBusy,"more opens all formats in floating dock without conversion");main.Dock.Close();main.Close();
  File.WriteAllLines(Path.Combine(dir,"wheel-tests.txt"),log);app.Shutdown();return 0;
 }catch(Exception ex){log.Add(ex.ToString());File.WriteAllLines(Path.Combine(dir,"wheel-tests.txt"),log);if(app!=null)app.Shutdown();return 1;}}
 public static int Flow(string[] args){string target=args[1],dir=args[2];Directory.CreateDirectory(dir);var files=args.Skip(3).Where(File.Exists).Select(Path.GetFullPath).ToArray();var app=new Application(){ShutdownMode=ShutdownMode.OnExplicitShutdown};var main=new MainWindow(true);Backend.Initialize(main.Pref).Wait();if(!Backend.Ready||files.Length==0)return 2;main.Pref.Output=dir;main.Dock=new FloatingDock(main,true);main.Dock.Show();var source=Backend.Detect(files[0]);var wheel=new RadialCompass(files,main.Engine.Common(files),source==null?"":source.Category,2,choice=>main.RunWheelChoice(files,choice),true);int index=Array.IndexOf(wheel.Targets,target);if(index<0)return 3;wheel.Show();var timer=new DispatcherTimer(){Interval=TimeSpan.FromMilliseconds(150)};DateTime start=DateTime.UtcNow;bool chosen=false;int result=1;timer.Tick+=(s,e)=>{if(!chosen||main.Dock.IsBusy){if((DateTime.UtcNow-start).TotalSeconds<90)return;main.Dock.Stop();}else if(main.Dock.TestOutputs.Length==files.Length)result=0;timer.Stop();Save(main.Dock,Path.Combine(dir,"wheel-result.png"));File.WriteAllLines(Path.Combine(dir,"wheel-flow-tests.txt"),new[]{"Target: "+target,"Inputs: "+files.Length,"Outputs: "+main.Dock.TestOutputs.Length,"Result: "+(result==0?"PASS":"FAIL")}.Concat(main.Dock.TestOutputs));app.Shutdown(result);};timer.Start();main.Dispatcher.BeginInvoke(new Action(()=>{wheel.ConfirmAt(WheelModel.Polar(152,-90+360.0*index/wheel.Targets.Length));chosen=true;}));app.Run();return result;}
}
}
